"""Embed docs/assets/sync.js (the web auto-sync) into the app: app/lib/podsync.generated.ts."""
import json
from pathlib import Path
src = Path("docs/assets/sync.js").read_text()
Path("app/lib/podsync.generated.ts").write_text(
    "// generated by tools/gen_podsync.py from docs/assets/sync.js — do not edit\n"
    f"export const PODSYNC_JS = {json.dumps(src, ensure_ascii=False)};\n")
print("ok", len(src))
